import { outlineOf, type SourceOutline } from "./source-outline.ts";

export interface SourceFile {
  /** Relative to the mapped folder, with forward slashes. */
  readonly path: string;
  readonly text: string;
}

/** Everything above this line in a map is written by hand and kept; everything below is generated. */
export const GENERATED_MARKER =
  "<!-- Generated by `npm run maps` from the code; edit only above this line. -->";

const HANDWRITTEN_PLACEHOLDER =
  "What this part owns, what it talks to and how, its traps, and what is still open.";

/**
 * The handwritten part stays a map: Owns, Talks to, Traps and Spec links, never the behaviour the spec states.
 * `maps:check` fails a map past either cap.
 */
export const HANDWRITTEN_CHARACTER_CAP = 10_000;
export const HANDWRITTEN_LINE_CAP = 400;

/** Why a map's handwritten part is over its caps, in words; none when it fits. */
export function handwrittenProblems(text: string): string[] {
  const handwritten = text.split(GENERATED_MARKER)[0]?.trimEnd() ?? "";
  const size =
    handwritten.length > HANDWRITTEN_CHARACTER_CAP
      ? [
          `its handwritten part is ${handwritten.length} characters, over ${HANDWRITTEN_CHARACTER_CAP}`,
        ]
      : [];
  const lines = handwritten
    .split("\n")
    .flatMap((line, index) =>
      line.length > HANDWRITTEN_LINE_CAP
        ? [`line ${index + 1} is ${line.length} characters, over ${HANDWRITTEN_LINE_CAP}`]
        : [],
    );
  return [...size, ...lines];
}

/** The map's text: its handwritten part, kept from the existing map, then the generated part. */
export function mapText(
  title: string,
  existing: string | undefined,
  files: readonly SourceFile[],
): string {
  const handwritten =
    existing?.split(GENERATED_MARKER)[0]?.trimEnd() ?? `# ${title}\n\n${HANDWRITTEN_PLACEHOLDER}`;
  return `${handwritten}\n\n${GENERATED_MARKER}\n\n${generatedPart(files)}`;
}

export function generatedPart(files: readonly SourceFile[]): string {
  const sorted = files.toSorted((a, b) => byFolderThenName(a.path, b.path));
  const sources = sorted.filter((file) => !isTest(file.path));
  const outlines = new Map(sources.map((file) => [file.path, outlineOf(file.text)]));
  const sections = [
    publicEntry(outlines),
    eventsSection(outlines),
    routesSection(outlines),
    tablesSection(outlines),
    filesSection(sorted, outlines),
  ];
  return `${sections.filter((section) => section !== undefined).join("\n\n")}\n`;
}

function publicEntry(outlines: ReadonlyMap<string, SourceOutline>): string | undefined {
  const entry = outlines.get("index.ts") ?? outlines.get("index.tsx");
  if (!entry || entry.exports.length === 0) return undefined;
  return `## Public entry (\`index.ts\`)\n\n${entry.exports.join(", ")}`;
}

function eventsSection(outlines: ReadonlyMap<string, SourceOutline>): string | undefined {
  const lines = [...outlines]
    .filter(([, outline]) => outline.events.length > 0)
    .map(([path, outline]) => `- \`${path}\`: ${outline.events.join(", ")}`);
  return lines.length > 0 ? `## Domain events\n\n${lines.join("\n")}` : undefined;
}

function routesSection(outlines: ReadonlyMap<string, SourceOutline>): string | undefined {
  const lines = [...outlines.values()].flatMap((outline) =>
    outline.routes.map((route) => `- \`${route.method} ${route.path}\`: ${route.handler}`),
  );
  return lines.length > 0 ? `## HTTP routes (under \`/api\`)\n\n${lines.join("\n")}` : undefined;
}

function tablesSection(outlines: ReadonlyMap<string, SourceOutline>): string | undefined {
  const lines = [...outlines]
    .filter(([, outline]) => outline.tables.length > 0)
    .map(([path, outline]) => `- \`${path}\`: ${outline.tables.join(", ")}`);
  return lines.length > 0 ? `## Tables\n\n${lines.join("\n")}` : undefined;
}

/** Each folder's files with what they export, then its tests by name. */
function filesSection(
  files: readonly SourceFile[],
  outlines: ReadonlyMap<string, SourceOutline>,
): string {
  const folders = new Map<string, SourceFile[]>();
  for (const file of files) {
    folders.set(folderOf(file.path), [...(folders.get(folderOf(file.path)) ?? []), file]);
  }
  const blocks = [...folders].map(([folder, inFolder]) => {
    const sources = inFolder
      .filter((file) => !isTest(file.path) && !isListedAsEntry(file.path, outlines))
      .map((file) => {
        const exported = outlines.get(file.path)?.exports ?? [];
        const name = `\`${nameOf(file.path)}\``;
        return exported.length > 0 ? `- ${name}: ${exported.join(", ")}` : `- ${name}`;
      });
    const tests = inFolder.filter((file) => isTest(file.path)).map((file) => nameOf(file.path));
    const testLine = tests.length > 0 ? [`- Tests: ${tests.join(", ")}`] : [];
    const lines = [...sources, ...testLine];
    return lines.length > 0
      ? [`### ${folder === "" ? "./" : `${folder}/`}`, "", ...lines].join("\n")
      : undefined;
  });
  return `## Files\n\n${blocks.filter((block) => block !== undefined).join("\n\n")}`;
}

/** The public entry has a section of its own. */
function isListedAsEntry(path: string, outlines: ReadonlyMap<string, SourceOutline>): boolean {
  return /^index\.tsx?$/.test(path) && (outlines.get(path)?.exports.length ?? 0) > 0;
}

/** The folder's own files first, then its subfolders; code-point order, the same on every system. */
function byFolderThenName(a: string, b: string): number {
  const [folderA, folderB] = [folderOf(a), folderOf(b)];
  if (folderA !== folderB) {
    if (folderA === "") return -1;
    if (folderB === "") return 1;
  }
  const [keyA, keyB] = folderA === folderB ? [a, b] : [folderA, folderB];
  return keyA < keyB ? -1 : keyA > keyB ? 1 : 0;
}

function isTest(path: string): boolean {
  return /\.test\.tsx?$/.test(path);
}

function folderOf(path: string): string {
  return path.includes("/") ? path.slice(0, path.lastIndexOf("/")) : "";
}

function nameOf(path: string): string {
  return path.slice(path.lastIndexOf("/") + 1);
}
